static inline u64 rng64(){
    static u64 x=(u64)(chrono::steady_clock::now().time_since_epoch().count())*10150724397891781847ULL;
    const u64 c=0xd07ebc63274654c7ull;
    x+=c;
    __uint128_t t=(__uint128_t)x*(x^c);
    return t^(t>>64);
}

void runcase(){
    int n,m;
    cin >> n >> m;
    vector<u64> a(n);
    for(int i=0;i<m;i++){
        int l,r;
        cin >> l >> r;
        l--;
        u64 h=rng64();
        a[l]^=h;
        if(r<n)a[r]^=h;
    }
    for(int i=1;i<n;i++)a[i]^=a[i-1];
    map<u64,int> last;
    vector<int> dp(n),pre(n,-1);
    deque<int> dq{0};
    last[a[0]]=0;
    int st=n,ed=-1;
    for(int i=1;i<n;i++){
        dp[i]=dp[dq.front()]+1;
        pre[i]=dq.front();
        if(last.count(a[i])){
            int p=last[a[i]];
            st=min(st,p);
            ed=i;
            while(!dq.empty()&&dq.front()<=p){
                dq.pop_front();
            }
        }
        if(!dq.empty()&&chmin(dp[i],dq.front())){
            pre[i]=dq.front();
        }
        while(!dq.empty()&&dp[i]<dp[dq.back()]){
            dq.pop_back();
        }
        dq.emplace_back(i);
        last[a[i]]=i;
    }
    vector<int> pos;
    for(int i=dq.front();i>0;i=pre[i]){
        pos.emplace_back(i);
    }
    if(ed!=-1&&a[st]==a[ed]){
        pos.emplace_back(st);
    }
    if(SZ(pos)%2==1)pos.emplace_back(n);
    SORT(pos);
    int h=SZ(pos)/2;
    cout << h << "\n";
    for(int i=0;i<h;i++){
        cout << pos[i]+1 << " " << pos[i+h] << "\n";
    }
}

