void add(char ch, int cnt, int z) {
    for (int i = 0; i < cnt; i++) {
        mv += ch;
        zc.push_back(z);
    }
}

int route(int r, int c) {
    mv = "";
    zc.clear();
    int up = min(r - 1, n - 3);
    add('U', up, 3);
    add('D', n - 3 - up, 2);
    int p = r - up;
    if (p == 3) {
        add('R', n - c, 3);
        add('L', c - 1, 2);
        add('U', 2, 2);
        return 1;
    }
    add('L', c - 1, 2);
    add('R', n - c, 1);
    add('D', 1, 1);
    if (p == 1) {
        add('D', 1, 0);
        return 0;
    }
    add('U', 1, 1);
    return 1;
}

int main() {
    cin >> n;
    for (int r = 1; r <= n; r++) {
        for (int c = 1; c <= n; c++) {
            int last = route(r, c);
            vector<string> g(n, string(n, '1'));
            int x1 = 0, x2 = n - 1, y1 = 0, y2 = n - 1;
            for (int i = 0; i < (int)mv.size(); i++) {
                int nxt = i + 1 < (int)mv.size() ? zc[i + 1] : last;
                int k = zc[i] - nxt;
                if (mv[i] == 'U') {
                    for (int j = 0; j < k; j++) g[x1][y1 + j] = '0';
                    x1++;
                } else if (mv[i] == 'D') {
                    for (int j = 0; j < k; j++) g[x2][y1 + j] = '0';
                    x2--;
                } else if (mv[i] == 'L') {
                    for (int j = 0; j < k; j++) g[x1 + j][y1] = '0';
                    y1++;
                } else {
                    for (int j = 0; j < k; j++) g[x1 + j][y2] = '0';
