#include <bits/stdc++.h>

using i64 = long long;

constexpr int B = 25;

int cnt[1 << B];

void solve() {
    int n;
    std::cin >> n;
    std::vector<int> a(n);
    for (int i = 0; i < n; i++) std::cin >> a[i];
    i64 ans = 0;
    std::vector next(n + 1, std::array<int, B>());
    std::vector ord(n, std::array<char, B>());
    next[n].fill(n);
    for (int i = n - 1; i >= 0; i--) {
        next[i] = next[i + 1];
        for (int b = 0; b < B; b++) if (~a[i] >> b & 1) next[i][b] = i;
        std::iota(ord[i].begin(), ord[i].end(), 0);
        std::sort(ord[i].begin(), ord[i].end(), [&](char x, char y) { return next[i][x] < next[i][y]; });
    }
    std::vector<std::vector<std::pair<int, int>>> occ(n + 1);
    for (int b = 0; b < B; b++) {
        int c = 0;
        for (int i = n - 1; i >= 0; i--) {
            c ^= a[i];
            if (a[i] >> b & 1) {
                int v = 0;
                for (int j = b; j < B; j++) if (next[i][j] != i) v |= 1 << j;
                for (int j = 0; j < B; ) {
                    int k = j;
                    bool f = false;
                    while (k < B && next[i][ord[i][j]] == next[i][ord[i][k]]) {
                        if (ord[i][k] >= b) f = true;
                        k++;
                    }
                    if (!f) {
                        j = k;
                        continue;
                    }
                    if (next[i][ord[i][j]] != i) {
                        occ[i].emplace_back((c ^ v) >> b, 1);
                        occ[next[i][ord[i][j]]].emplace_back((c ^ v) >> b, -1);
                    }
                    while (j < k) {
                        if (v >> ord[i][j] & 1) v ^= 1 << ord[i][j];
                        j++;
                    }
                    if (~v >> b & 1) break;
                }
            }
        }
        c = 0;
        for (int i = n - 1; i >= 0; i--) {
            cnt[c >> b]++;
            c ^= a[i];
            for (auto [x, m] : occ[i]) {
                ans += 1LL * cnt[x] * m * (1 << b);
            }
        }
        c = 0;
        for (int i = n - 1; i >= 0; i--) {
            cnt[c >> b] = 0;
            c ^= a[i];
        }
        for (int i = 0; i <= n; i++) occ[i].clear();
    }
    std::cout << ans << "\n";
}

int main() {
    std::ios::sync_with_stdio(0);
    std::cin.tie(0);

    int t;
    std::cin >> t;
    while (t--) solve();
}

