void solve_first() {
    int n, h;
    cin >> n >> h; int m = (1 << h) - 1;
    string s;
    cin >> s;
    s = "0" + s;

    string ans(m + 1, '0');
    for(int i = 1; i <= m; i++) {
        if(i & i - 1) {
            int idx = i - __lg(i) - 1;
            if(idx > n) continue;
            ans[i] = s[idx];
            for(int j = 0; j < h; j++) {
                if(i >> j & 1) ans[1 << j] ^= s[idx] & 1;
            }
        }
    }

    string res(m + 1, '0');
    int idx = 1;
    function<void(int)> dfs = [&](int v) {
        char cr = ans[idx++];
        res[v] = cr;

        vector<int> c;
        if(2 * v + 1 <= m) {
            c.push_back(2 * v);
            c.push_back(2 * v + 1);
            if(cr & 1) swap(c[0], c[1]);
        }

        for(auto to : c) dfs(to);
    };
    dfs(1);
    res.erase(res.begin());

    cout << res << '\n';
}

